/**
 * `output: row(<table>)` — the action returns one row of this table.
 *
 * Runtime: a Zod object built from the table's columns, so the generated
 * route parses `execute`'s result through the real row shape (Dates are
 * still Dates here; they serialize to ISO strings on the wire).
 * Compile time: the CLI harvester can't see table columns (tables are
 * stubbed), so its stand-in emits an `x-quickback-row` marker instead —
 * the compiler resolves that to the resource's OpenAPI component and to
 * `Api.<table>.Row` in quickback.gen.ts.
 */
export function row<T extends Table>(table: T): z.ZodType<InferSelectModel<T>> {
  // Index signature, not `Record<…>`: some helper variants export a `Record`
  // row type alias that shadows the global utility type.
  const shape: { [column: string]: z.ZodType } = {};
  for (const [key, column] of Object.entries(getTableColumns(table))) {
    let field: z.ZodType =
      column.dataType === "string" ? z.string()
        : column.dataType === "number" ? z.number()
          : column.dataType === "boolean" ? z.boolean()
            : column.dataType === "date" ? z.union([z.date(), z.string()])
              : z.unknown();
    if (!column.notNull) field = field.nullable();
    shape[key] = field;
  }
  return z.object(shape) as unknown as z.ZodType<InferSelectModel<T>>;
}

// ── Declared pagination (`pagination:`) ───────────────────────────────

/** Page envelope metadata — the same fields a CRUD collection read reports. */
export interface QbPageMeta {
  /** Rows on this page. */
  count: number;
  /** Resolved page size (after default / max clamping). */
  pageSize: number;
  /** More rows exist after this page (from a `limit + 1` probe). */
  hasMore: boolean;
  /** Pass back as `starting_after`; `null` on the final page. */
  nextCursor: string | null;
  /** The sort this page was produced under. */
  sort: string;
}

export interface QbPageResult<TRow> {
  data: TRow[];
  pagination: QbPageMeta;
}

/** Row shape of a `select` projection: each selected column's data type (nullable when the column is). */
export type QbSelectedRow<S> = {
  [K in keyof S]: S[K] extends { _: { data: infer D; notNull: infer N } }
    ? N extends true ? D : D | null
    : S[K] extends SQL<infer R> ? R : unknown;
};

/** Options for one `page.query` call. */
export interface QbPageQueryOptions {
  /** Caller predicate, AND-merged with the table's firewall and the keyset boundary. */
  where?: SQL | undefined;
  /** Named sort override (default: `input.sort`, else the declared default). */
  sort?: string;
}

/**
 * The `page` helper injected into `execute` when the action declares
 * `pagination:`. Every read goes through the scoped `db` (firewall + soft
 * delete), the request cursor is validated against this action / table /
 * sort / input, and the result is the CRUD page envelope.
 */
export interface QbActionPage {
  /** Resolved page size. */
  readonly limit: number;
  /** Resolved sort name. */
  readonly sort: string;
  /** The raw `starting_after` cursor the request carried, if any. */
  readonly cursor: string | null;
  /** Fetch one page of the declared table. */
  query<T extends Table>(table: T, opts?: QbPageQueryOptions): Promise<QbPageResult<InferSelectModel<T>>>;
  /** Fetch one page as a projection; sort keys are read internally and stripped when not selected. */
  query<T extends Table, S extends { [key: string]: unknown }>(table: T, opts: QbPageQueryOptions & { select: S }): Promise<QbPageResult<QbSelectedRow<S>>>;
  /** Lower-level: the keyset predicate for the request cursor (undefined on the first page). */
  keyset(table: Table, sort?: string): SQL | undefined;
  /** Lower-level: the ORDER BY terms of `sort` on `table`. */
  orderBy(table: Table, sort?: string): SQL[];
  /** Lower-level: turn `limit + 1` over-fetched rows in sort order into a page with `nextCursor`. */
  finish<TRow extends { [key: string]: any }>(rows: TRow[], sort?: string): QbPageResult<TRow>;
}

/** `pagination:` — see the docs (/define/actions/defining#paginated-actions-pagination). */
export interface QbPaginationConfig {
  /** The paged table (authored name). Defaults to the bound table on a record action. */
  table?: string;
  /** Named sorts: `'column'` ascending, `'-column'` descending; each must end in a unique key. */
  sorts: { [name: string]: readonly string[] };
  /** Sort used when the request names none. Default: the first declared sort. */
  defaultSort?: string;
  /** Page size bounds. Default `{ default: 50, max: 100 }`. */
  limit?: { default?: number; max?: number };
  /** Legacy request names read as the cursor when `starting_after` is absent (e.g. `['before']`); excluded from the cursor context. */
  cursorAliases?: readonly string[];
}

/** The request parameters a paginated action reads. Spread by `pageInput()`. */
export const PAGE_PARAMS = {
  limit: z.coerce.number().int().min(1).optional(),
  starting_after: z.string().max(2048).optional(),
  sort: z.string().optional(),
};

/**
 * `input: pageInput({ ...fields })` — the action's own fields plus the
 * pagination parameters (`limit`, `starting_after`, `sort`), so they are
 * validated, typed and published in OpenAPI / MCP.
 */
export function pageInput<T extends z.ZodRawShape>(shape: T = {} as T) {
  return z.object({ ...shape, ...PAGE_PARAMS });
}

const PAGE_META_SCHEMA = z.object({
  count: z.number().int(),
  pageSize: z.number().int(),
  hasMore: z.boolean(),
  nextCursor: z.string().nullable(),
  sort: z.string(),
});

/**
 * `output: page(row(table))` — the page envelope `{ data, pagination }`.
 * Pass a second `z.object` to add domain fields beside the page.
 */
export function page<TItem extends z.ZodType, TExtra extends z.ZodRawShape = {}>(
  item: TItem,
  extra?: z.ZodObject<TExtra>,
) {
  const base = z.object({ data: z.array(item), pagination: PAGE_META_SCHEMA });
  return (extra ? base.extend(extra.shape) : base) as z.ZodObject<{ data: z.ZodArray<TItem>; pagination: typeof PAGE_META_SCHEMA } & TExtra>;
}

