type DefinedAction<T = any> = T & { readonly [ACTION_BRAND]: true };

function brand<T extends object>(config: T): DefinedAction<T> {
  return Object.assign({}, config, { [ACTION_BRAND]: true as const }) as DefinedAction<T>;
}

import type { orders } from "../orders";

// The bound table, re-exported so action files can import it from this
// helper (single import; typed with the generated schema's injected columns).
export { orders } from "../orders";

type Record = typeof orders.$inferSelect;

/**
 * Define a record-based or standalone action in feature `orders`.
 *
 * - Record-based actions (no `path:`) mount at `/orders/:id/<filename>`
 *   and receive `record` typed as `typeof orders.$inferSelect`.
 * - Standalone actions set `path:`. They get no `record`.
 *
 * One signature, discriminated union on `path`. Two-overload shapes break
 * contextual typing of unannotated `execute` lambdas — TS infers the
 * lambda's params from the first overload's signature and then can't fit
 * the second one.
 */
export function defineAction<
  const TAccess,
  TInput = unknown,
  TRecord = Record,
  TResult = unknown,
  const TRefs = undefined,
  TQuery = undefined,
  const TRaw extends boolean | undefined = undefined,
  const TWebhook = undefined,
  const TOperator = undefined,
  const TConfig extends object = object,
>(config: TConfig & (
  | RecordActionConfig<TRecord, typeof orders, TInput, TAccess, TResult, TRefs, TQuery>
  | StandaloneActionConfig<TInput, TAccess, TResult, TRefs, TQuery, TRaw, TWebhook, TOperator>
)): DefinedAction<TConfig> {
  return brand(config);
}

